import {splitPlace,shareState,makeTen,nearHundred,clockAngles} from './kids-math.js';
export const settings={count:6,a:3,b:2,sub:8,removed:new Set(),counted:new Set(),submode:'take',comparison:3,number:23,unpack:false,borrowStep:0,groups:3,per:4,total:12,people:3,given:0,den:4,parts:new Set([0]),pattern:'ab',start:2,step:2,reveal:false,shape:'triangle',angle:0,day:'shop',price:7,pay:10,hour:3,minute:0,length:6,method:'ten',first:9,second:6,small:7,twoDigit:23,nearA:98,nearB:97};
const fmt=n=>n.toLocaleString('en-IN');
const range=(key,label,min,max,value,step=1)=>`<label class="kid-range" for="k-${key}"><span>${label}</span><output id="out-${key}">${value}</output></label><input id="k-${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}">`;
const select=(key,label,options,value)=>`<label class="kid-range" for="k-${key}">${label}</label><select id="k-${key}" data-setting="${key}">${options.map(([v,n])=>`<option value="${v}" ${v===value?'selected':''}>${n}</option>`).join('')}</select>`;
const eq=(text)=>`<div class="kid-equation" aria-live="polite">${text}</div>`;
const note=text=>`<p class="scene-note">${text}</p>`;
const dots=(count,color='purple',tag='span')=>`<div class="objects ${color}">${Array.from({length:count},(_,i)=>`<${tag} class="object" aria-label="${i+1}">★</${tag}>`).join('')}</div>`;
const numberLine=(max,from,to)=>`<div class="number-line" aria-label="${from} ${to}">${Array.from({length:max+1},(_,i)=>`<span class="${i>=Math.min(from,to)&&i<=Math.max(from,to)?'path':''} ${i===to?'land':''}">${i}</span>`).join('')}</div>`;
export function controls(id,bi){const s=settings;switch(id){case'count':return range('count',bi('How many stars?','कितने तारे?'),0,20,s.count);case'compare':case'add':return range('a',bi('First group','पहला समूह'),0,10,s.a)+range('b',bi('Second group','दूसरा समूह'),0,10,s.b);case'subtract':return select('submode',bi('What shall we explore?','क्या देखें?'),[['take',bi('Take away','हटाएं')],['difference',bi('Find the difference','अंतर निकालें')]],s.submode)+range('sub',bi('Starting balloons','शुरुआती गुब्बारे'),0,20,s.sub)+(s.submode==='difference'?range('comparison',bi('Second group','दूसरा समूह'),0,20,s.comparison):'');case'place':return range('number',bi('Build a number','संख्या बनाएं'),0,99,s.number);case'multiply':return range('groups',bi('How many groups?','कितने समूह?'),1,6,s.groups)+range('per',bi('Objects in each group','हर समूह में वस्तुएं'),0,6,s.per);case'share':return range('total',bi('Stars to share','बांटने के तारे'),0,24,s.total)+range('people',bi('Friends','मित्र'),2,6,s.people);case'fractions':return range('den',bi('Equal parts in the whole','पूरे में बराबर भाग'),2,8,s.den);case'patterns':return select('pattern',bi('Pattern rule','पैटर्न का नियम'),[['ab',bi('Circle, star (AB)','वृत्त, तारा (AB)')],['aab',bi('Circle, circle, star (AAB)','वृत्त, वृत्त, तारा (AAB)')],['number',bi('Growing numbers','बढ़ती संख्याएं')]],s.pattern)+(s.pattern==='number'?range('start',bi('Start at','यहां से शुरू'),0,10,s.start)+range('step',bi('Add each time','हर बार जोड़ें'),1,5,s.step):'');case'shapes':return select('shape',bi('Choose a shape','आकार चुनें'),[['triangle',bi('Triangle','त्रिभुज')],['square',bi('Square','वर्ग')],['rectangle',bi('Rectangle','आयत')],['circle',bi('Circle','वृत्त')]],s.shape)+range('angle',bi('Turn the shape (degrees)','आकार घुमाएं (डिग्री)'),0,360,s.angle,15);case'everyday':return select('day',bi('Choose a little adventure','छोटा अभियान चुनें'),[['shop',bi('Little shop','छोटी दुकान')],['clock',bi('Clock explorer','घड़ी खोजें')],['ruler',bi('Measure a pencil','पेंसिल मापें')]],s.day)+(s.day==='shop'?range('price',bi('Toy price (₹)','खिलौने की कीमत (₹)'),1,20,s.price)+range('pay',bi('Money given (₹)','दिए पैसे (₹)'),0,30,s.pay):s.day==='clock'?range('hour',bi('Hour','घंटा'),1,12,s.hour)+range('minute',bi('Minutes','मिनट'),0,55,s.minute,5):range('length',bi('Pencil length (cm)','पेंसिल की लंबाई (सेमी)'),1,10,s.length));case'mental':return select('method',bi('Choose a method','विधि चुनें'),[['ten',bi('Make a ten','दस बनाएं')],['nine',bi('Multiply by 9','9 से गुणा')],['eleven',bi('Multiply by 11','11 से गुणा')],['hundred',bi('Near 100 · Vedic base method','100 के पास · वैदिक आधार विधि')]],s.method)+(s.method==='ten'?range('first',bi('First number','पहली संख्या'),1,9,s.first)+range('second',bi('Second number','दूसरी संख्या'),1,10,s.second):s.method==='nine'?range('small',bi('Number of groups','समूहों की संख्या'),1,12,s.small):s.method==='eleven'?range('twoDigit',bi('Two-digit number','दो अंकों की संख्या'),10,99,s.twoDigit):range('nearA',bi('First number','पहली संख्या'),91,99,s.nearA)+range('nearB',bi('Second number','दूसरी संख्या'),91,99,s.nearB));}}
export function scene(id,bi){const s=settings;switch(id){case'count':return `<div class="count-counter"><strong>${s.counted.size}</strong><span>${bi('tapped','छुए')} / ${s.count}</span></div><div class="objects count-objects">${Array.from({length:s.count},(_,i)=>`<button class="object ${s.counted.has(i)?'counted':''}" data-count="${i}" aria-pressed="${s.counted.has(i)}" aria-label="${bi('Star','तारा')} ${i+1}">${s.counted.has(i)?[...s.counted].indexOf(i)+1:'★'}</button>`).join('')||`<div class="empty-basket">◯<strong>0</strong><span>${bi('No stars. This is zero.','कोई तारा नहीं। यह शून्य है।')}</span></div>`}</div>${eq(`${s.count} ${bi('stars','तारे')}`)}${note(bi('Count each object once. Tap again to start counting that object afresh.','हर वस्तु एक बार गिनें। दोबारा छूकर उसे फिर गिन सकते हैं।'))}<button class="kid-button light" data-action="reset-count">${bi('Count again','फिर गिनें')}</button>`;
case'compare':return `<div class="paired-groups"><div><h3>${bi('First group','पहला समूह')} · ${s.a}</h3>${dots(s.a)}</div><div><h3>${bi('Second group','दूसरा समूह')} · ${s.b}</h3>${dots(s.b,'mint')}</div></div>${eq(`${s.a} ${s.a===s.b?'=':s.a>s.b?'>':'<'} ${s.b}`)}${note(s.a===s.b?bi('Every star has a partner. The groups are equal.','हर तारे का साथी है। समूह बराबर हैं।'):bi(`Match ${Math.min(s.a,s.b)} pairs. There are ${Math.abs(s.a-s.b)} extra in the ${s.a>s.b?'first':'second'} group.`,` ${Math.min(s.a,s.b)} जोड़ियां मिलाएं। ${s.a>s.b?'पहले':'दूसरे'} समूह में ${Math.abs(s.a-s.b)} ज्यादा हैं।`))}`;
case'add':return `<div class="sum-groups"><div>${dots(s.a)}<b>${s.a}</b></div><strong>+</strong><div>${dots(s.b,'mint')}<b>${s.b}</b></div></div>${eq(`${s.a} + ${s.b} = ${s.a+s.b}`)}${numberLine(20,s.a,s.a+s.b)}${note(bi(`Start at ${s.a}. Count on ${s.b} steps to ${s.a+s.b}.`,` ${s.a} से शुरू करें। ${s.b} कदम आगे ${s.a+s.b} तक गिनें।`))}<button class="kid-button light" data-action="hops">${bi('Play the hops','छलांगें चलाएं')}</button>`;
case'subtract':{const removed=s.removed.size;if(s.submode==='difference')return `<div class="paired-groups"><div><h3>${s.sub}</h3>${dots(s.sub)}</div><div><h3>${s.comparison}</h3>${dots(s.comparison,'mint')}</div></div>${eq(`${Math.max(s.sub,s.comparison)} − ${Math.min(s.sub,s.comparison)} = ${Math.abs(s.sub-s.comparison)}`)}${note(bi('Pair the objects. The unmatched objects show the difference.','वस्तुओं की जोड़ियां बनाएं। बिना जोड़ी की वस्तुएं अंतर दिखाती हैं।'))}`;return `<div class="objects balloons">${Array.from({length:s.sub},(_,i)=>`<button class="balloon ${s.removed.has(i)?'taken':''}" data-remove="${i}" aria-pressed="${s.removed.has(i)}" aria-label="${bi('Balloon','गुब्बारा')} ${i+1}${s.removed.has(i)?bi(', taken away',', हटाया गया'):''}"><span>${s.removed.has(i)?'×':'●'}</span><i></i></button>`).join('')||note(bi('Zero balloons. There is nothing to take away.','शून्य गुब्बारे। हटाने को कुछ नहीं है।'))}</div>${eq(`${s.sub} − ${removed} = ${s.sub-removed}`)}<div class="story-numbers"><span>${bi('Started','शुरू')}<b>${s.sub}</b></span><span>${bi('Taken away','हटाए')}<b>${removed}</b></span><span>${bi('Still here','बचे')}<b>${s.sub-removed}</b></span></div>${numberLine(20,s.sub,s.sub-removed)}<button class="kid-button light" data-action="reset-remove">${bi('Bring them all back','सभी वापस लाएं')}</button>`;}
case'place':{const p=splitPlace(s.number,s.unpack);if(s.borrowStep===3)p.ones-=8;return `<div class="place-board"><div><h3>${bi('TENS','दहाई')} · ${p.tens}</h3><div class="tens-rods">${Array.from({length:p.tens},()=>`<span class="ten-rod">${'<i></i>'.repeat(10)}</span>`).join('')}</div></div><div><h3>${bi('ONES','इकाई')} · ${p.ones}</h3>${dots(p.ones,'mint')}</div></div>${eq(`${p.tens} × 10 + ${p.ones} = ${s.borrowStep===3?15:s.number}`)}<button class="kid-button light" data-action="unpack" ${s.number<10||s.borrowStep===3?'disabled':''}>${s.borrowStep===3?bi('Story complete','कहानी पूरी'):s.unpack?bi('Bundle ten ones back','दस इकाइयां फिर बांधें'):bi('Unpack one ten','एक दहाई खोलें')}</button>${note(bi('A ten trades for ten ones. The number stays the same. Use the guided 23 − 8 example below to see regrouping in action.','एक दहाई के बदले दस इकाइयां। संख्या वही रहती है। नीचे 23 − 8 का उदाहरण चलाकर पुनर्समूहन देखें।'))}<div class="borrow-story"><strong>23 − 8</strong><p>${s.borrowStep===0?bi('First predict the answer, then follow the objects.','पहले उत्तर का अनुमान लगाएं, फिर वस्तुएं देखें।'):s.borrowStep===1?bi('We have 2 tens and 3 ones. We need to remove 8 ones, but only 3 ones are loose.','हमारे पास 2 दहाई और 3 इकाई हैं। 8 इकाई हटानी हैं, लेकिन खुली इकाइयां केवल 3 हैं।'):s.borrowStep===2?bi('Trade one ten for ten ones. Now we have 1 ten and 13 ones. The total is still 23.','एक दहाई खोलकर दस इकाइयां बनाएं। अब 1 दहाई और 13 इकाई हैं। कुल अभी भी 23 है।'):bi('Take away 8 of the 13 ones. 1 ten and 5 ones remain: 23 − 8 = 15.','13 में से 8 इकाई हटाएं। 1 दहाई और 5 इकाई बचे: 23 − 8 = 15।')}</p><button class="kid-button light" data-action="borrow-demo">${s.borrowStep===0||s.borrowStep===3?bi('Play the 23 − 8 story','23 − 8 की कहानी चलाएं'):s.borrowStep===1?bi('Unpack a ten for this story','इस कहानी के लिए दहाई खोलें'):bi('Take away 8 ones','8 इकाई हटाएं')}</button></div>`;}
case'multiply':return `<div class="array" style="--cols:${Math.max(s.per,1)}" aria-label="${s.groups} ${bi('groups of','समूह')} ${s.per}">${Array.from({length:s.groups*s.per},(_,i)=>`<span class="array-dot row${Math.floor(i/Math.max(1,s.per))%2}">★</span>`).join('')||note(bi('Every group is empty.','हर समूह खाली है।'))}</div>${eq(`${s.groups} × ${s.per} = ${s.groups*s.per}`)}${note(Array(s.groups).fill(s.per).join(' + ')+` = ${s.groups*s.per}`)}<button class="kid-button light" data-action="rotate-array" ${s.per===0?'disabled':''}>${bi('Turn the array','पंक्तियां घुमाएं')}</button>`;
case'share':{const d=shareState(s.total,s.people,s.given),complete=s.given>=Math.floor(s.total/s.people)*s.people;return `<div class="sharing-bowls">${d.shares.map((n,i)=>`<div class="share-bowl"><span class="friend-face">${['☺','☻','☺','☻','☺','☻'][i]}</span><strong>${bi('Friend','मित्र')} ${i+1}</strong>${dots(n,i%2?'mint':'purple')}<b>${n}</b></div>`).join('')}</div><div class="share-pool"><span>${bi('Not shared yet','अभी नहीं बंटे')}: <b>${d.left}</b></span>${dots(d.left,'peach')}</div><div class="play-actions"><button class="kid-button" data-action="share-one" ${complete?'disabled':''}>${bi('Give the next star','अगला तारा दें')}</button><button class="kid-button light" data-action="share-all">${bi('Share equally','बराबर बांटें')}</button></div>${eq(complete?`${s.total} ÷ ${s.people} = ${d.each} ${d.remainder?bi(`remainder ${d.remainder}`,`शेष ${d.remainder}`):''}`:`${s.given} ${bi('given out','बांटे')} · ${d.left} ${bi('left','बचे')}`)}${note(complete?bi(`Each gets ${d.each} whole stars. ${d.remainder} remain after equal whole-star shares.`,`हर एक को ${d.each} पूरे तारे। बराबर पूरी वस्तुएं बांटने के बाद ${d.remainder} बचते हैं।`):bi('Go around in order, one star per friend. Equal sharing may leave a remainder.','क्रम से हर मित्र को एक तारा दें। बराबर बांटने पर शेष बच सकता है।'))}`;}
case'fractions':return `<div class="fraction-whole" style="--pieces:${s.den}">${Array.from({length:s.den},(_,i)=>`<button data-piece="${i}" class="fraction-piece ${s.parts.has(i)?'filled':''}" aria-label="${bi('Equal piece','बराबर टुकड़ा')} ${i+1}" aria-pressed="${s.parts.has(i)}">${s.parts.has(i)?'✓':''}</button>`).join('')}</div>${eq(`<span class="written-fraction" role="img" aria-label="${s.parts.size}/${s.den}"><b>${s.parts.size}</b><b>${s.den}</b></span><span>${bi('of one whole','एक पूरे का भाग')}</span>`)}${note(bi(`${s.parts.size} selected out of ${s.den} equal parts. ${s.parts.size===s.den?'All parts selected: one whole.':s.parts.size===0?'No parts selected: zero.':'Every piece has the same size.'}`,`${s.den} बराबर भागों में से ${s.parts.size} चुने। ${s.parts.size===s.den?'सभी भाग चुने: एक पूरा।':s.parts.size===0?'कोई भाग नहीं चुना: शून्य।':'हर टुकड़े का आकार बराबर है।'}`))}`;
case'patterns':{const seq=s.pattern==='ab'?['●','★']:['●','●','★'];return `<div class="pattern-sequence">${Array.from({length:7},(_,i)=>`<span class="pattern-cell ${i===6?'mystery':''} ${s.pattern==='number'?'number':seq[i%seq.length]==='●'?'symbol-circle':'symbol-star'}">${i===6&&!s.reveal?'?':s.pattern==='number'?s.start+i*s.step:seq[i%seq.length]}</span>`).join('')}</div><button class="kid-button light" data-action="reveal-pattern">${bi('Reveal the next one','अगला देखें')}</button>${note(s.reveal?(s.pattern==='number'?bi(`Add ${s.step} each time.`,`हर बार ${s.step} जोड़ें।`):bi(`The unit ${seq.join(' ')} repeats in the same order.`,`इकाई ${seq.join(' ')} उसी क्रम में दोहराती है।`)):bi('Say your prediction and explain the rule before revealing.','देखने से पहले अपना अनुमान और नियम बताएं।'))}`;}
case'shapes':{const names={triangle:bi('Triangle','त्रिभुज'),square:bi('Square','वर्ग'),rectangle:bi('Rectangle','आयत'),circle:bi('Circle','वृत्त')},side={triangle:3,square:4,rectangle:4,circle:0}[s.shape];return `<div class="shape-stage"><div class="big-shape ${s.shape}" style="transform:rotate(${s.angle}deg)" role="img" aria-label="${names[s.shape]}"></div></div>${eq(names[s.shape])}<div class="story-numbers"><span>${bi('Straight sides','सीधी भुजाएं')}<b>${side}</b></span><span>${bi('Corners','कोने')}<b>${side}</b></span></div>${note(bi('Turning changes the direction, not the shape. A square is also a special rectangle.','घुमाने से दिशा बदलती है, आकार नहीं। वर्ग भी विशेष प्रकार का आयत है।'))}`;}
case'everyday':if(s.day==='shop')return `<div class="little-shop"><span class="toy-block">✦</span><div><span>${bi('Toy price','खिलौने की कीमत')}</span><strong>₹${s.price}</strong></div><div><span>${bi('Money given','दिए पैसे')}</span><strong>₹${s.pay}</strong></div></div>${eq(s.pay>=s.price?`₹${s.pay} − ₹${s.price} = ₹${s.pay-s.price}`:bi(`Need ₹${s.price-s.pay} more`,`₹${s.price-s.pay} और चाहिए`))}${note(s.pay>=s.price?bi(`The shopkeeper gives ₹${s.pay-s.price} back.`,`दुकानदार ₹${s.pay-s.price} वापस देता है।`):bi('There is not enough money yet. Add more to pay for the toy.','अभी पैसे कम हैं। खिलौना खरीदने के लिए और जोड़ें।'))}`;else if(s.day==='clock'){const a=clockAngles(s.hour,s.minute);return `<svg class="kid-clock" viewBox="0 0 240 240" role="img" aria-label="${s.hour}:${String(s.minute).padStart(2,'0')}"><circle cx="120" cy="120" r="108" fill="#fff" stroke="#dcd2ee" stroke-width="7"/>${Array.from({length:12},(_,i)=>{const r=(i+1)*Math.PI/6;return `<text x="${120+87*Math.sin(r)}" y="${126-87*Math.cos(r)}" text-anchor="middle">${i+1}</text>`;}).join('')}<line x1="120" y1="120" x2="120" y2="65" stroke="#7152b8" stroke-width="9" stroke-linecap="round" transform="rotate(${a.hour} 120 120)"/><line x1="120" y1="120" x2="120" y2="42" stroke="#42977b" stroke-width="5" stroke-linecap="round" transform="rotate(${a.minute} 120 120)"/><circle cx="120" cy="120" r="8" fill="#7152b8"/></svg>${eq(`${s.hour}:${String(s.minute).padStart(2,'0')}`)}${note(bi('Short purple hand: hours. Long green hand: minutes. The hour hand moves gradually between numbers.','छोटी बैंगनी सुई: घंटे। लंबी हरी सुई: मिनट। घंटे की सुई संख्याओं के बीच धीरे-धीरे चलती है।'))}`;}else return `<div class="ruler-stage"><div class="pencil" style="width:${s.length*10}%">✎</div><div class="ruler">${Array.from({length:11},(_,i)=>`<span>${i}</span>`).join('')}</div></div>${eq(`${s.length} cm`)}${note(bi('Start at zero. Count equal centimetre intervals, not the number of marks.','शून्य से शुरू करें। बराबर सेंटीमीटर के अंतर गिनें, निशानों की संख्या नहीं।'))}`;
case'mental':if(s.method==='ten'){const m=makeTen(s.first,s.second);return `<div class="ten-frame">${Array.from({length:10},(_,i)=>`<span class="${i<s.first?'first':i<s.first+m.moved?'second':''}">${i<s.first+m.moved?'●':''}</span>`).join('')}</div>${dots(m.remainder,'mint')}${eq(`${s.first} + ${s.second} = ${s.first+s.second}`)}<div class="reason-box">${bi(`Move ${m.moved} from the second group into the empty spaces.`,`दूसरे समूह से ${m.moved} खाली जगहों में रखें।`)}<b>${s.first} + ${m.moved} + ${m.remainder} = ${m.reachesTen?'10':s.first+m.moved} + ${m.remainder} = ${m.total}</b>${bi('We moved objects; we did not add or lose any.','हमने वस्तुएं खिसकाईं; कोई बढ़ी या घटी नहीं।')}</div>`;}else if(s.method==='nine')return `<div class="nine-array">${Array.from({length:s.small},()=>`<div>${'<i></i>'.repeat(9)}<i class="crossed"></i></div>`).join('')}</div>${eq(`${s.small} × 9 = ${s.small*9}`)}<div class="reason-box">${bi('Start with ten in every row. Remove one from each row.','हर पंक्ति में दस से शुरू करें। हर पंक्ति से एक हटाएं।')}<b>${s.small} × (10 − 1) = ${s.small*10} − ${s.small} = ${s.small*9}</b></div>`;else if(s.method==='eleven')return `<div class="eleven-blocks"><span>${s.twoDigit*10}<small>× 10</small></span><b>+</b><span>${s.twoDigit}<small>× 1</small></span></div>${eq(`${s.twoDigit} × 11 = ${s.twoDigit*11}`)}<div class="reason-box">${bi('Eleven groups are ten groups plus one group.','ग्यारह समूह = दस समूह और एक समूह।')}<b>${s.twoDigit} × (10 + 1) = ${s.twoDigit*10} + ${s.twoDigit} = ${s.twoDigit*11}</b>${bi('This also works when the middle digits add to ten or more: regroup instead of joining digits.','बीच के अंकों का योग दस या अधिक होने पर भी यह काम करता है: अंकों को चिपकाने के बजाय पुनर्समूहन करें।')}</div>`;else{const h=nearHundred(s.nearA,s.nearB);return `<div class="base-square" role="img" aria-label="${bi('A 100 by 100 square with two strips removed and their overlap restored','100 गुणा 100 के वर्ग में दो पट्टियां हटाकर साझा भाग लौटाया गया')}"><span>100 × 100</span><div class="strip-right" style="width:${h.left}%"></div><div class="strip-bottom" style="height:${h.right}%"></div><i style="width:${h.left}%;height:${h.right}%"></i></div>${eq(`${s.nearA} × ${s.nearB} = ${fmt(h.result)}`)}<div class="reason-box">${bi(`The gaps from 100 are ${h.left} and ${h.right}. Remove both strips, then restore their overlap once because it was removed twice.`,`100 से अंतर ${h.left} और ${h.right} हैं। दोनों पट्टियां हटाएं, फिर साझा भाग एक बार वापस जोड़ें क्योंकि वह दो बार हट गया था।`)}<b>10,000 − ${h.left*100} − ${h.right*100} + ${h.overlap} = ${fmt(h.result)}</b><b>(${s.nearA} − ${h.right}) × 100 + ${h.left} × ${h.right} = ${fmt(h.result)}</b>${bi('This playground uses whole numbers from 91 to 99 so the final small part stays below 100.','यह प्रयोग 91 से 99 तक की पूरी संख्याएं लेता है ताकि आखिरी छोटा भाग 100 से कम रहे।')}</div>`;}}
}
export function playground(id,bi){return `<div class="play-controls" id="play-controls">${controls(id,bi)}</div><div class="play-scene" id="play-scene">${scene(id,bi)}</div>`;}
export function bindPlayground(id,bi){const s=settings;const redraw=()=>{const active=document.activeElement;const attr=['data-count','data-remove','data-piece','data-action'].find(a=>active?.hasAttribute(a));const focus=attr?'['+attr+'="'+active.getAttribute(attr)+'"]':null;document.querySelector('#play-scene').innerHTML=scene(id,bi);bindActions();if(focus){const target=document.querySelector(focus);if(target&&!target.disabled)target.focus({preventScroll:true});}};const rebuild=()=>{document.querySelector('#play-controls').innerHTML=controls(id,bi);bindSettings();redraw();};
 function bindSettings(){document.querySelectorAll('[data-setting]').forEach(el=>el[el.tagName==='SELECT'?'onchange':'oninput']=()=>{const key=el.dataset.setting;s[key]=el.tagName==='SELECT'?el.value:Number(el.value);if(key==='count')s.counted.clear();if(key==='sub')s.removed.clear();if(key==='number'){s.unpack=false;s.borrowStep=0;}if(key==='den')s.parts=new Set([...s.parts].filter(i=>i<s.den));if(key==='total'||key==='people')s.given=0;s.reveal=false;const out=document.querySelector('#out-'+key);if(out)out.textContent=s[key];if(el.tagName==='SELECT')rebuild();else redraw();});}
 function bindActions(){document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{const n=+b.dataset.count;s.counted.has(n)?s.counted.delete(n):s.counted.add(n);redraw();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const n=+b.dataset.remove;s.removed.has(n)?s.removed.delete(n):s.removed.add(n);redraw();});document.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{const n=+b.dataset.piece;s.parts.has(n)?s.parts.delete(n):s.parts.add(n);redraw();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'reset-count':s.counted.clear();break;case'reset-remove':s.removed.clear();break;case'unpack':s.unpack=!s.unpack;s.borrowStep=0;break;case'borrow-demo':s.number=23;s.borrowStep=s.borrowStep===3?1:s.borrowStep+1;s.unpack=s.borrowStep>=2;rebuild();return;case'rotate-array':[s.groups,s.per]=[s.per,s.groups];rebuild();return;case'share-one':s.given=Math.min(Math.floor(s.total/s.people)*s.people,s.given+1);break;case'share-all':s.given=Math.floor(s.total/s.people)*s.people;break;case'reveal-pattern':s.reveal=true;break;case'hops':if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('.number-line .path').forEach((el,i)=>el.animate([{transform:'translateY(0)'},{transform:'translateY(-12px)'},{transform:'translateY(0)'}],{duration:400,delay:i*140}));return;}redraw();});}
 bindSettings();bindActions();
}
